style.css:
@-moz-document domain("roblox.com") {
/* Esconde o valor real do Robux */
    #nav-robux-amount, 
    .rbx-text-navbar-right, 
    #robux-amount-display {
        visibility: hidden !important;
        position: relative !important;
    }

    /* Injeta o valor fake de 350M */
    #nav-robux-amount::after, 
    .rbx-text-navbar-right::after, 
    #robux-amount-display::after {
        content: "350M" !important;
        visibility: visible !important;
        position: absolute !important;
        left: 0 !important;
        top: 0 !important;
        color: #FFFFFF !important; /* Cor branca do texto padrão */
        font-weight: bold !important;
    }
}
